-- Real database integration tests. Fixtures rolled back; no Auth users or Storage objects created.
begin;
do $$
declare provider_auth uuid; provider_user integer; pid integer; balai_a integer; balai_b integer; tpl integer; org integer; team integer; team2 integer; team_b integer; person integer; person_b integer; orphan integer; qualification integer; state jsonb; r record; expected_a boolean; expected_b boolean; n integer; initial_person_count integer;
begin
 select u.pengguna_id,u.auth_user_id into provider_user,provider_auth from public.pengguna u join public.pengguna_peran pp using(pengguna_id) join public.peran pr using(peran_id) where pr.nama='penyedia_jasa' and not coalesce(u.terkunci,false) limit 1;
 select t.tim_id,p.paket_id,p.balai_id,p.penyedia_id,q.template_id into team,pid,balai_a,org,tpl from public.tim_survei t join public.paket_kontrak p using(paket_id) join public.checklist_pengisian q using(paket_id) join public.checklist_template ct using(template_id) where q.status='DISETUJUI' and ct.no_dokumen='JM-PERSIAPAN-TAHAP0' order by p.paket_id,t.tim_id limit 1;
 if team is null or org is null then raise exception 'Need an existing team on approved preparation';end if;
 select min(scope_balai_id) into balai_b from public.pengguna_peran where scope_balai_id<>balai_a;
 select count(*) into initial_person_count from public.personel;
 perform set_config('request.jwt.claim.sub',provider_auth::text,true);
 execute 'set local role authenticated';
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Bad","peran":"Operator","status":"LULUS"}');raise exception 'Spoofed state allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Bad","peran":null}');raise exception 'Null peran allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":null,"peran":"Operator"}');raise exception 'Null name allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Bad","peran":"Operator","pengalaman_tahun":-1}');raise exception 'Negative experience allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Bad","peran":"Operator","pengalaman_tahun":1.5}');raise exception 'Fraction experience allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Bad","peran":"Operator","mulai":"2026-02-30"}');raise exception 'Invalid calendar date allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Bad","peran":"Operator","selesai":"2026-10-01"}');raise exception 'End without start allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_personel_tim(pid,2147483647,'{"nama":"Bad","peran":"Operator"}');raise exception 'Missing team allowed';exception when no_data_found then null;end;
 execute 'reset role';
 alter table public.audit_trail add constraint test_person_audit_failure check(aksi<>'ASSIGN_PERSONNEL') not valid;
 execute 'set local role authenticated';
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Rollback audit","nik_internal":"ROLLBACK-PERSON-AUDIT","peran":"Operator"}');raise exception 'Assignment audit not enforced';exception when check_violation then null;end;
 execute 'reset role';alter table public.audit_trail drop constraint test_person_audit_failure;
 if (select count(*) from public.personel)<>initial_person_count then raise exception 'Failed audit left new person';end if;
 execute 'set local role authenticated';
 state:=public.daftar_personel_tim(pid,team,'{"nama":" UJIAN - Operator rollback ","nik_internal":" ROLLBACK-PERSON-12 ","pendidikan":null,"pengalaman_tahun":0,"peran":" Operator ","mulai":"2026-10-18"}');person:=(state#>>'{personel,personel_id}')::int;
 if state#>>'{personel,penyedia_id}'<>org::text or state#>>'{personel,nama}'<>'UJIAN - Operator rollback' or state#>>'{anggota,peran}'<>'Operator' or state->>'kelayakan_belum_dinilai'<>'true' or state#>>'{personel,pendidikan}' is not null then raise exception 'Personnel defaults/context invalid';end if;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Duplicate internal id","nik_internal":"rollback-person-12","peran":"Operator"}');raise exception 'Duplicate internal ID allowed';exception when unique_violation then null;end;
 begin perform public.daftar_personel_tim(pid,team,jsonb_build_object('personel_id',person,'peran','Operator','mulai','2026-10-18'));raise exception 'Duplicate membership period allowed';exception when unique_violation then null;end;
 begin perform public.daftar_personel_tim(pid,team,jsonb_build_object('personel_id',person,'nama','Reparent','peran','Operator'));raise exception 'Existing person renamed through assignment';exception when invalid_parameter_value then null;end;
 execute 'reset role';
 insert into public.tim_survei(paket_id,jenis_survei_id,nama_tim) select pid,jenis_survei_id,'Rollback second personnel team' from public.tim_survei where tim_id=team returning tim_id into team2;
 update public.personel set penyedia_id=null where personel_id=person;
 execute 'set local role authenticated';
 begin perform public.daftar_personel_tim(pid,team2,jsonb_build_object('personel_id',person,'peran','Operator'));raise exception 'Mismatched provider allowed';exception when invalid_parameter_value then null;end;
 execute 'reset role';update public.personel set penyedia_id=org where personel_id=person;
 execute 'set local role authenticated';
 state:=public.daftar_personel_tim(pid,team2,jsonb_build_object('personel_id',person,'peran','Operator'));
 if state#>>'{personel,personel_id}'<>person::text then raise exception 'Existing person was duplicated';end if;
 state:=public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"SKK","nomor":" ROLLBACK-SKK-12 ","jenjang":null,"berlaku_sd":null}');qualification:=(state#>>'{kualifikasi,kualifikasi_id}')::int;
 if state#>>'{kualifikasi,dokumen_id}' is not null or state#>>'{kualifikasi,berlaku_sd}' is not null or state->>'kelayakan_belum_dinilai'<>'true' then raise exception 'Qualification fabricated evidence/expiry/approval';end if;
 begin perform public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"SKK","nomor":"rollback-skk-12"}');raise exception 'Duplicate qualification allowed';exception when unique_violation then null;end;
 begin perform public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"SKK","nomor":"Bad","dokumen_id":4}');raise exception 'Forged evidence allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"BAD","nomor":"Bad"}');raise exception 'Unknown qualification allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"SKK","nomor":null}');raise exception 'Null number allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"SKK","nomor":"Bad date","berlaku_sd":"2026-02-30"}');raise exception 'Invalid qualification date allowed';exception when invalid_parameter_value then null;end;
 begin perform public.daftar_kualifikasi_personel(pid,team,2147483647,'{"jenis":"SKK","nomor":"Bad"}');raise exception 'Nonmember qualification allowed';exception when no_data_found then null;end;
 execute 'reset role';
 alter table public.audit_trail add constraint test_qualification_audit_failure check(aksi<>'CREATE_PERSONNEL_QUALIFICATION') not valid;
 execute 'set local role authenticated';
 begin perform public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"SKA","nomor":"ROLLBACK-AUDIT-QUAL"}');raise exception 'Qualification audit not enforced';exception when check_violation then null;end;
 execute 'reset role';alter table public.audit_trail drop constraint test_qualification_audit_failure;
 if exists(select 1 from public.kualifikasi_personel where nomor='ROLLBACK-AUDIT-QUAL') then raise exception 'Failed audit left qualification';end if;
 insert into public.paket_kontrak(paket_id,balai_id,penyedia_id,nama_paket,status) overriding system value values(2100000012,balai_b,org,'Rollback personnel package B','DRAFT');
 insert into public.checklist_pengisian(paket_id,template_id,status) values(2100000012,tpl,'DRAFT');
 insert into public.tim_survei(paket_id,jenis_survei_id,nama_tim) select 2100000012,jenis_survei_id,'Rollback personnel team B' from public.tim_survei where tim_id=team returning tim_id into team_b;
 execute 'set local role authenticated';
 begin perform public.daftar_personel_tim(2100000012,team_b,'{"nama":"Gate blocked","peran":"Operator"}');raise exception 'Unapproved preparation allowed';exception when object_not_in_prerequisite_state then null;end;
 begin perform public.daftar_personel_tim(pid,team_b,jsonb_build_object('personel_id',person,'peran','Operator'));raise exception 'Cross-package team allowed';exception when no_data_found then null;end;
 begin perform public.daftar_kualifikasi_personel(pid,team_b,person,'{"jenis":"SKK","nomor":"Wrong package"}');raise exception 'Cross-package qualification allowed';exception when no_data_found then null;end;
 execute 'reset role';update public.checklist_pengisian set status='DISETUJUI' where paket_id=2100000012;
 execute 'set local role authenticated';
 state:=public.daftar_personel_tim(2100000012,team_b,'{"nama":"Other Balai person","peran":"Operator"}');person_b:=(state#>>'{personel,personel_id}')::int;
 perform public.daftar_kualifikasi_personel(2100000012,team_b,person_b,'{"jenis":"PELATIHAN_QA_QC_DJBM","nomor":"TRAINING-ROLLBACK"}');
 execute 'reset role';
 insert into public.personel(penyedia_id,nama) values(org,'Unassigned person') returning personel_id into orphan;
 for r in select u.auth_user_id,u.pengguna_id,pr.nama,pp.scope_balai_id,pp.scope_paket_id from public.pengguna u join public.pengguna_peran pp using(pengguna_id) join public.peran pr using(peran_id) loop
  expected_a:=r.nama in ('penyedia_jasa','admin','direktorat') or (r.nama='pic_balai' and r.scope_balai_id=balai_a and (r.scope_paket_id is null or r.scope_paket_id=pid));
  expected_b:=r.nama in ('penyedia_jasa','admin','direktorat') or (r.nama='pic_balai' and r.scope_balai_id=balai_b and (r.scope_paket_id is null or r.scope_paket_id=2100000012));
  perform set_config('request.jwt.claim.sub',r.auth_user_id::text,true);execute 'set local role authenticated';
  if exists(select 1 from public.personel where personel_id=person) is distinct from expected_a then raise exception 'Person A scope failed for %',r.nama;end if;
  if exists(select 1 from public.anggota_tim where tim_id=team and personel_id=person) is distinct from expected_a then raise exception 'Member scope failed';end if;
  if exists(select 1 from public.kualifikasi_personel where kualifikasi_id=qualification) is distinct from expected_a then raise exception 'Qualification A scope failed';end if;
  if exists(select 1 from public.personel where personel_id=person_b) is distinct from expected_b then raise exception 'Person B scope failed';end if;
  if exists(select 1 from public.kualifikasi_personel where personel_id=person_b) is distinct from expected_b then raise exception 'Qualification B scope failed';end if;
  if r.nama='pic_balai' and exists(select 1 from public.personel where personel_id=orphan) then raise exception 'PIC sees unassigned person';end if;
  if r.nama<>'penyedia_jasa' then
   begin perform public.daftar_personel_tim(pid,team,'{"nama":"Forbidden","peran":"Operator"}');raise exception 'Non-provider created person';exception when insufficient_privilege then null;end;
   begin perform public.daftar_kualifikasi_personel(pid,team,person,'{"jenis":"SKK","nomor":"Forbidden"}');raise exception 'Non-provider created qualification';exception when insufficient_privilege then null;end;
  end if;
  if has_table_privilege(current_user,'public.personel','INSERT') or has_table_privilege(current_user,'public.anggota_tim','UPDATE') or has_table_privilege(current_user,'public.kualifikasi_personel','DELETE') then raise exception 'Direct writes granted';end if;
  execute 'reset role';
 end loop;
 update public.pengguna set terkunci=true where pengguna_id=provider_user;
 perform set_config('request.jwt.claim.sub',provider_auth::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.personel where personel_id in (person,person_b,orphan)) or exists(select 1 from public.kualifikasi_personel where kualifikasi_id=qualification) then raise exception 'Locked user sees data';end if;
 begin perform public.daftar_personel_tim(pid,team,'{"nama":"Locked","peran":"Operator"}');raise exception 'Locked provider writes';exception when insufficient_privilege then null;end;
 execute 'reset role';
 if has_function_privilege('anon','public.daftar_personel_tim(integer,integer,jsonb)','EXECUTE') or has_function_privilege('anon','public.daftar_kualifikasi_personel(integer,integer,integer,jsonb)','EXECUTE') then raise exception 'Anonymous RPC enabled';end if;
end $$;
rollback;
select 'PASS: person/member registration, existing-person assignment, provider binding, qualification metadata, duplicate/input checks, role and Balai scopes, locked profile, gate, audit rollback and direct-write restrictions. All fixtures rolled back.' as verification;
